// One list drives the header, the footer and the sitemap, so a page cannot be in the menu and missing
// from the sitemap. Adding a page to the menu is one line here: `to` is checked against the real routes
// (src/routeTree.gen.ts, regenerated by "npm run dev" or "npm run build" when you add a route file),
// and the language-free path and the id are worked out from it.
import type { FileRouteTypes } from '@/routeTree.gen';

/**
 * Every public page under /$locale that needs no other parameter (the article page needs a slug, so it is
 * out). The admin pages (/$locale/admin...) are routes too but must never reach the header, the footer or
 * the sitemap, so they are excluded by type: adding one here does not compile.
 */
export type PageRoute = Exclude<
  Extract<FileRouteTypes['to'], `/$locale${string}`>,
  `${string}/$${string}/$${string}` | `/$locale/admin${string}`
>;

type NavInput = {
  to: PageRoute;
  labelKey: string;
  changefreq: 'daily' | 'weekly' | 'monthly' | 'yearly';
  priority: number;
};

export type NavItem = NavInput & {
  /** Stable key: "home" for the language root, otherwise the path without its slash ("about"). */
  id: string;
  /** '' is the language root (/ar). Otherwise the route path without the locale: '/about'. */
  path: string;
};

const LOCALE_PREFIX = '/$locale';

export function navItem(input: NavInput): NavItem {
  const path = input.to.slice(LOCALE_PREFIX.length);
  return { ...input, id: path === '' ? 'home' : path.slice(1), path };
}

export const NAV: readonly NavItem[] = [
  navItem({ to: '/$locale', labelKey: 'nav.home', changefreq: 'weekly', priority: 1 }),
  navItem({ to: '/$locale/about', labelKey: 'nav.about', changefreq: 'monthly', priority: 0.7 }),
  navItem({
    to: '/$locale/services',
    labelKey: 'nav.services',
    changefreq: 'monthly',
    priority: 0.8,
  }),
  navItem({ to: '/$locale/news', labelKey: 'nav.news', changefreq: 'weekly', priority: 0.7 }),
  navItem({ to: '/$locale/contact', labelKey: 'nav.contact', changefreq: 'yearly', priority: 0.6 }),
];
